package com.madar.files;
import org.json.*;import java.util.*;import java.io.IOException;
/** Scene graph parity with creative.js. Nothing in a model response is executable. */
final class MotionCreative {
 /** Must list every icon and drawn illustration creative.js can emit (qa/motion-parity.test.cjs checks it). */
 static final List<String> ICONS=Arrays.asList("play","file","audio","check","spark","arrow","grain","book","shield","image","phone","chat","tea","teapot","pastry","coffee","seating","clock24","location","flame","mint","people","delivery","stars","offer","sweets","cold","sandwich","fries","storefront","menu");
 static void validate(JSONObject c)throws Exception{
  if(!Arrays.asList("plain","orbit","grid","radial","split").contains(c.getString("backdrop")))throw new IOException("خلفية غير صالحة");JSONArray a=c.getJSONArray("elements");if(a.length()<1||a.length()>16)throw new IOException("عدد عناصر غير صالح");List<JSONObject> texts=new ArrayList<>();
  for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i);String kind=e.getString("kind");if(!Arrays.asList("text","shape","image","device","icon","line","metric").contains(kind)||!Arrays.asList("rise","left","right","scale","draw","fade").contains(e.getString("motion"))||!Arrays.asList("ink","accent","card","muted","background").contains(e.getString("color")))throw new IOException("عنصر غير صالح");double x=MotionProject.number(e,"x",0,.96),y=MotionProject.number(e,"y",0,.96),w=MotionProject.number(e,"w",.02,1),h=MotionProject.number(e,"h",.005,1);MotionProject.number(e,"delay",0,.7);if(x+w>1.001||y+h>1.001)throw new IOException("عنصر خارج المشهد");if(kind.equals("text")||kind.equals("metric")){MotionProject.text(e,"text",100,false);MotionProject.number(e,"size",20,110);texts.add(e);}if((kind.equals("image")||kind.equals("device"))&&!e.getString("asset").matches("asset_[a-f0-9]{32}\\.jpg"))throw new IOException("صورة غير صالحة");if(kind.equals("icon")&&!ICONS.contains(e.getString("icon")))throw new IOException("رمز غير صالح");}
  for(int i=0;i<texts.size();i++)for(int k=i+1;k<texts.size();k++){JSONObject x=texts.get(i),y=texts.get(k);if(Math.min(x.getDouble("x")+x.getDouble("w"),y.getDouble("x")+y.getDouble("w"))-Math.max(x.getDouble("x"),y.getDouble("x"))>.008&&Math.min(x.getDouble("y")+x.getDouble("h"),y.getDouble("y")+y.getDouble("h"))-Math.max(x.getDouble("y"),y.getDouble("y"))>.008)throw new IOException("النصوص متداخلة");}
 }
 static Set<String> assets(JSONObject p)throws Exception{Set<String> names=new LinkedHashSet<>();JSONArray scenes=p.getJSONArray("scenes");for(int i=0;i<scenes.length();i++){JSONObject s=scenes.getJSONObject(i);if(!s.optString("image").isEmpty())names.add(s.getString("image"));if(s.optString("graphic").equals("creative")){JSONArray a=s.getJSONObject("composition").getJSONArray("elements");for(int k=0;k<a.length();k++)if(Arrays.asList("image","device").contains(a.getJSONObject(k).optString("kind")))names.add(a.getJSONObject(k).getString("asset"));}}return names;}
}
